function pendingCode(){const raw=new URL(entryURL);for(const[id,r]of Object.entries(PAN)){if(!hostMatch(r,raw.hostname))continue;const q=raw.searchParams.get('pwd')||raw.searchParams.get('p'),hash=raw.hash.slice(1);if(q&&/^[A-Za-z0-9]{3,8}$/.test(q))return{id,r,code:q};if(/^[A-Za-z0-9]{3,8}$/.test(hash))return{id,r,code:hash};const records=get('baguaCloudPending',[]);let ref;try{ref=new URL(document.referrer);}catch{}const current=shareId(raw);const record=records.find(x=>x.id===id&&Date.now()-x.time<180000&&(x.share&&x.share===current||x.host===raw.hostname&&x.path===raw.pathname||IS_FRAME&&ref&&x.host===ref.hostname&&x.path===ref.pathname));if(record)return{id,r,code:record.code,record};}return null;}
