function boxEntries(){const entries=[...cfg.engines.filter(e=>e.inBox&&e.kind!=='image').map(e=>({key:'e:'+e.id,name:e.name,engine:e})),...cfg.boxTools.filter(id=>BOX_TOOL_IDS.includes(id)).map(id=>({key:'t:'+id,name:LABELS[id],tool:id}))];const order=new Map(cfg.boxOrder.map((key,i)=>[key,i]));return entries.map((item,i)=>({...item,rank:order.has(item.key)?order.get(item.key):cfg.boxOrder.length+i})).sort((a,b)=>a.rank-b.rank);}
