function placePanel(p){if(!p||p.classList.contains('settings'))return;if(p.classList.contains('centered-input-search')){p.style.left='50%';p.style.top='50%';p.style.transform='translate(-50%,-50%)';return;}const anchor={...pointerPosition};const place=()=>{if(!p.isConnected)return;const r=p.getBoundingClientRect();p.style.left=Math.max(8,Math.min(innerWidth-r.width-8,anchor.clientX+8))+'px';p.style.top=Math.max(8,Math.min(innerHeight-r.height-8,anchor.clientY+8))+'px';};p.style.transform='none';p.style.maxHeight='calc(100vh - 16px)';p.style.overflow='auto';place();const observer=new ResizeObserver(place);observer.observe(p);const cleanup=new MutationObserver(()=>{if(!p.isConnected){observer.disconnect();cleanup.disconnect();}});cleanup.observe(root,{childList:true});}
