const hiIconJobs=new Map();
function iconHome(e){try{return 'https://'+(ICON_HOSTS[e.id]||new URL(e.url).hostname)+'/';}catch{return null;}}
async function discoverHiIcon(e){
 const home=iconHome(e);if(!home)return null;
 if(hiIconJobs.has(home))return hiIconJobs.get(home);
 const job=(async()=>{const cache=get('baguaHiIcons',{}),old=cache[home];if(old&&Date.now()-old.time<7*86400000)return old.url||null;
 const found=[];let page;try{page=await request(home);}catch{return null;}
 const base=page.finalUrl||home,doc=new DOMParser().parseFromString((page.responseText||'').slice(0,3000000),'text/html');
 const add=(src,sizes='',type='')=>{try{const u=new URL(src,base);if(!/^https?:$/.test(u.protocol))return;const vector=/svg/i.test(type)||/\.svg(?:[?#]|$)/i.test(u.href),n=Math.max(0,...[...sizes.matchAll(/(\d+)x\d+/g)].map(x=>Number(x[1])));if(vector||n>=48)found.push({url:u.href,score:vector?10000:n});}catch{}};
 for(const link of doc.querySelectorAll('link[rel]')){const rel=(link.getAttribute('rel')||'').toLowerCase();if(rel.split(/\s+/).some(x=>['icon','apple-touch-icon','apple-touch-icon-precomposed'].includes(x)))add(link.getAttribute('href'),link.getAttribute('sizes')||(/apple-touch/.test(rel)?'180x180':''),link.getAttribute('type')||'');}
 if(!found.length){const m=doc.querySelector('link[rel="manifest"]');if(m)try{const u=new URL(m.getAttribute('href'),base);if(u.origin===new URL(base).origin){const r=await request(u.href),manifest=JSON.parse(r.responseText);for(const i of manifest.icons||[]){const src=new URL(i.src,u.href).href;add(src,i.sizes||'',i.type||'');}}}catch{}}
 found.sort((a,b)=>b.score-a.score);const url=found[0]?.url||null;cache[home]={time:Date.now(),url};const keys=Object.keys(cache);while(keys.length>150)delete cache[keys.shift()];put('baguaHiIcons',cache);return url;
 })().catch(()=>null);hiIconJobs.set(home,job);return job;
}

