function offlineBadge(e){const label=String(e.name||'网站').slice(0,3).replace(/[&<>"']/g,'');const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="96" height="96"><rect width="96" height="96" rx="19" fill="#e6edf7"/><text x="48" y="58" text-anchor="middle" font-size="${label.length>2?25:35}" fill="#275c8d" font-family="sans-serif">${label}</text></svg>`;return 'data:image/svg+xml;base64,'+btoa(unescape(encodeURIComponent(svg)));}
