function tile(p,name,icon,glyph,fn){const b=el('button',undefined,p);b.className='tile';b.setAttribute('aria-label',name);b.onmousedown=e=>e.preventDefault();if(icon){const image=el('img',undefined,b);attachIcon(image,cfg.engines.find(e=>e.name===name)||{name,icon},b);}else el('div',glyph||name.slice(0,2),b).className='glyph';el('span',name,b);b.onclick=()=>{closeBox();safe(fn);};return b;}

