const isEdit=n=>!!n?.closest?.('input,textarea,select,[contenteditable="true"],[contenteditable=""],[role="textbox"]');
function textTarget(text){const info=cloudInfo(text);const m=text.match(/https?:\/\/[^\s<>"，。]+/i);return info||m?{kind:'link',value:info?.url||m[0],text,shareText:text}:{kind:'text',value:text,text,shareText:text};}
function showBox(point){if(!cfg.box||drag||Date.now()<blocked)return;const text=window.getSelection()?.toString().trim();if(!text)return;closeBox();toolbar=el('div',undefined,root);toolbar.className='panel toolbar '+cfg.boxSize;const d=textTarget(text);for(const entry of boxEntries()){if(entry.engine){const e=entry.engine;tile(toolbar,e.name,iconURL(e),'',()=>runEngine(e,text,true));}else{const a=action(entry.tool,d);tile(toolbar,a.name,null,a.symbol,a.run);}}tile(toolbar,'设置',"data:image/svg+xml;base64,",'☯',showSettings);const rect=toolbar.getBoundingClientRect();const x=point?.clientX??innerWidth/2,y=point?.clientY??innerHeight/3;toolbar.style.left=Math.max(8,Math.min(innerWidth-rect.width-8,x-rect.width/2))+'px';toolbar.style.top=Math.max(8,Math.min(innerHeight-rect.height-8,(cfg.boxPosition==='below'?y+14:y-rect.height-14)))+'px';}
async function runEngine(e,text,fromBox=false){if(e.mode==='direct')return open(e.url);if(e.mode==='doubao-image'){if(!e.enabled&&!fromBox)throw Error('此网站未放入搜索盘');return startAITransfer(e,text,true);}if(e.mode==='ai-chat'){if(!e.enabled&&!fromBox)throw Error('此网站未放入搜索盘');return startAITransfer(e,text,false);}if(!e.enabled&&!fromBox)throw Error('此网站未放入搜索盘');if(e.mode==='fill'||e.mode==='post'){const id=crypto.randomUUID();put('baguaEntry:'+id,{...e,text,time:Date.now()});const u=new URL(e.url);u.hash='bagua-entry='+id;open(u.href);return;}if(!e.url.includes('%s'))throw Error('网址规则缺少 %s，请重新采集或编辑');let target=e.url.replace(/%s/g,encodeURIComponent(text));if(e.id==='trtencent'){const url=new URL(target);if(url.hostname==='transmart.qq.com'){const codes={zh:'zh',jp:'ja',kor:'ko',fra:'fr',spa:'es'};url.searchParams.set('sourcelang',codes[languageOf(text)]||languageOf(text));url.searchParams.set('targetlang',codes[targetLanguage(text)]||targetLanguage(text));target=url.href;}}open(target);}

