async function startAITransfer(e,text,isImage){const service=aiService(e.url);if(isImage&&service!=='doubao')throw Error('豆包识图使用豆包');const id=recordId(),packet={id,service,time:Date.now(),kind:isImage?'image':'text',prompt:isImage?'请用中文识别图片中的主要内容，说明可能的名称和用途；无法确定的地方请明确说明。':String(text)};
 if(isImage){if(!/^(https?:|data:image\/|blob:)/i.test(text))throw Error('没有可读取的图片');const blob=await blobOf(text);if(!/^image\//.test(blob.type)||blob.size>5*1024*1024)throw Error('请使用5MB以内的图片');packet.data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('图片读取失败'));r.readAsDataURL(blob);});}
 const index=get('ai-transfer-index',[]);const keep=[];for(const item of Array.isArray(index)?index:[]){if(Date.now()-item.time>10*60*1000)put('ai-transfer:'+item.id,null);else keep.push(item);}while(keep.length>=2)put('ai-transfer:'+keep.shift().id,null);put('ai-transfer:'+id,packet);keep.push({id,time:packet.time});put('ai-transfer-index',keep);const url=new URL(e.url);url.hash='bagua-ai='+id;open(url.href,true);toast(isImage?'请在豆包页面确认传入图片':'请在AI页面确认填入内容');}
function findAIComposer(){const selectors=['textarea[data-testid*="chat"]','textarea[placeholder]','textarea','[contenteditable="true"][role="textbox"]','[contenteditable="true"]'];for(const selector of selectors){const list=[...document.querySelectorAll(selector)].filter(n=>visible(n)&&!n.closest('[role="dialog"]'));if(list.length)return list.at(-1);}return null;}
function findAIImageInput(){const list=[...document.querySelectorAll('input[type="file"]')].filter(n=>!n.disabled&&/image|\.png|\.jpe?g|\.webp/i.test(n.accept||''));if(list.length===1)return list[0];return list.find(n=>n.closest('[class*="upload"],[class*="Upload"],[data-testid*="upload"],[data-testid*="chat"]'))||null;}
function receiveAITransfer(){const match=/^#bagua-ai=([\w-]+)$/.exec(new URL(entryURL).hash);if(!match)return;let service;try{service=aiService(location.href);}catch{return;}const key='ai-transfer:'+match[1],packet=get(key,null);if(!packet||packet.id!==match[1]||packet.service!==service||Date.now()-packet.time>10*60*1000){if(packet)put(key,null);toast('待处理内容已过期，请重新操作');return;}
 const p=panel('', 'textmodal');el('p',packet.kind==='image'?'在豆包确认图片和问题后发送；若需要，请先登录。':'确认后填入当前输入框，由你检查并发送。',p).className='muted';if(packet.kind==='image'){const im=el('img',undefined,p);im.src=packet.data;im.style.cssText='display:block;max-width:220px;max-height:160px;object-fit:contain;margin:0 auto 8px';}
 let imageAttached=false;const prompt=el('textarea',undefined,p);prompt.value=packet.prompt;prompt.setAttribute('aria-label','发送内容');
 button(p,packet.kind==='image'?'传入豆包':'填入输入框',async()=>{if(Date.now()-packet.time>10*60*1000)throw Error('内容已过期，请重新操作');const composer=findAIComposer();if(!composer)throw Error('未找到输入框，请先完成登录并打开新对话，再重试');const existing=(composer.value??composer.textContent??'').trim();if(existing&&existing!==prompt.value.trim())throw Error('当前输入框已有内容，请先清空，避免覆盖');
 if(packet.kind==='image'&&!imageAttached){const input=findAIImageInput();if(!input)throw Error('请先点击豆包的添加图片按钮，再回来重试');const blob=await(await fetch(packet.data)).blob(),w=input.ownerDocument.defaultView,dt=new w.DataTransfer();dt.items.add(new w.File([blob],'bagua-image.'+(blob.type.includes('png')?'png':blob.type.includes('webp')?'webp':blob.type.includes('gif')?'gif':'jpg'),{type:blob.type}));input.files=dt.files;input.dispatchEvent(new w.Event('input',{bubbles:true}));input.dispatchEvent(new w.Event('change',{bubbles:true}));imageAttached=true;}
 const destination=composer.isConnected?composer:findAIComposer();if(!destination)throw Error('图片已交给上传框；请复制问题后手动填入');destination.focus();fillField(destination,prompt.value);put(key,null);hide();toast(packet.kind==='image'?'已交给图片上传框；请检查上传结果后，在豆包点击发送':'已填入；请检查后点击发送');});
 button(p,'复制问题',()=>copy(prompt.value));if(packet.kind==='image')button(p,'下载图片',()=>saveImage({kind:'image',value:packet.data}));
}

