function wheelLabel(group,ring,i,a,id,color){const text=(x,y,value,size=17)=>{const n=svg('text',{x,y,fill:color,'text-anchor':'middle'},group);n.style.fontFamily='Arial,"Microsoft YaHei",sans-serif';n.style.fontSize=size+'px';n.style.fontWeight='600';n.textContent=value;};if(ring==='Outer'&&(i===1||i===3)){const raw=Array.from(a.name),chars=raw.length>8?[...raw.slice(0,7),'…']:raw;chars.forEach((ch,j)=>text(190+(i===1?147:-147),190-(chars.length-1)*20/2+6+j*20,ch));return;}const point=polar(ring==='Inner'?70:147,-90+i*90),limit=ring==='Inner'&&(i===1||i===3)?58:ring==='Inner'?100:112,lines=[];let line='',width=0;for(const ch of Array.from(a.name)){const cw=/[\x00-\xff]/.test(ch)?10:17;if(width+cw>limit&&line){lines.push(line);line='';width=0;}line+=ch;width+=cw;}if(line)lines.push(line);if(lines.length>2){lines.length=2;lines[1]=lines[1].slice(0,-1)+'…';}const symbol=id!=='ocr'&&a.symbol;if(symbol)text(point[0],point[1]-(ring==='Outer'?12:15),symbol,22);const first=symbol?(lines.length>1?8:15):(lines.length>1?-2:6);lines.forEach((value,j)=>text(point[0],point[1]+first+j*20,value));}

function drawWheel(p,type,onPick,d=null,preview=false){const con=el('div',undefined,p);con.className='wheel'+(preview?' preview':'');const drawing=svg('svg',{width:380,height:380,viewBox:'0 0 380 380'},con),paths=[];const wc=cfg.wheelColors||{};svg('circle',{cx:190,cy:190,r:178,fill:wc.outerLight||'#ffffff'},drawing);for(const[ring,r1,r2,labelR]of [['Outer',109,178,147],['Inner',34,109,73]])for(let i=0;i<4;i++){const id=cfg[type+ring][i],a=action(id,d||{kind:type,value:'',shareText:''}),g=svg('g',{class:'wb'},drawing),dark=(i%2===0)!==(ring==='Inner'),path=svg('path',{d:sectorPath(r1,r2,i),fill:dark?(ring==='Inner'?(wc.innerDark||'#454545'):(wc.outerDark||'#454545')):(ring==='Inner'?(wc.innerLight||'#ffffff'):(wc.outerLight||'#ffffff')),class:'sector'},g);const color=dark?'#fff':(ring==='Inner'?(wc.innerText||'#25313d'):(wc.outerText||'#25313d'));wheelLabel(g,ring,i,a,id,color);svg('title',{},g).textContent=a.name;path.onclick=()=>onPick(ring,i,a);paths.push({ring,i,path,a,g});if(preview){const pivot=polar(ring==='Inner'?70:147,-90+i*90);g.onpointerenter=()=>liftWheel(g,true,pivot[0],pivot[1],false);g.onpointerleave=()=>liftWheel(g,false,pivot[0],pivot[1],false);}}const cg=svg('g',{class:'wc'},drawing);const center=svg('circle',{cx:190,cy:190,r:34,fill:wc.center||'#ffffff',stroke:'#b6c5d3','stroke-width':2,class:'center'},cg);const image=svg('image',{href:"data:image/svg+xml;base64,",x:169,y:169,width:42,height:42,preserveAspectRatio:'xMidYMid meet'},cg);image.style.pointerEvents='none';cg.onpointerenter=()=>liftWheel(cg,true,190,190,true);cg.onpointerleave=()=>liftWheel(cg,false,190,190,true);if(!preview)center.onclick=closeWheel;return{con,paths,cg};}
function showWheel(d,x,y){closeBox();closeWheel();const type=d.kind==='image'?'image':d.kind==='link'?'link':'text',r=drawWheel(root,type,(_,__,a)=>{closeWheel();safe(a.run);},d),scale=Math.min(cfg.wheelScale/100,(innerWidth-12)/380,(innerHeight-12)/380),left=Math.max(6,Math.min(innerWidth-380*scale-6,x-190*scale)),top=Math.max(6,Math.min(innerHeight-380*scale-6,y-190*scale));wheel=r.con;wheel.style.cssText=`left:${left}px;top:${top}px;transform:scale(${scale})`;wheelInfo={...r,scale,left,top};}
