 if(!list.length){el('small','在“添加自定义网站”中选择“网站直达”即可添加。',card).className='muted';return;}
 for(const e of list){const row=el('div',undefined,card);row.className='direct-row';const im=el('img',undefined,row);im.className='iconpreview';attachIcon(im,e);const name=el('span',e.name,row);name.className='direct-name';name.title=e.name;const label=el('label',undefined,row),check=el('input',undefined,label);check.type='checkbox';check.checked=!!e.inPanel;label.append('功能面板');check.onchange=()=>{e.inPanel=check.checked;persist();};button(row,'删除',()=>{cfg.engines=cfg.engines.filter(x=>x.id!==e.id);persist();showSettings('engines');});}
