let repairingIcons=false;
async function usableStoredIcon(e){
 if(e.iconOrigin==='upload')return true;const src=iconCandidates(e)[0];if(!/^data:image\//i.test(src||'')||src===offlineBadge(e))return false;
 const im=new Image();im.src=src;try{if(im.decode)await im.decode();else await new Promise((resolve,reject)=>{if(im.complete){im.naturalWidth?resolve():reject(Error('invalid'));return;}im.onload=resolve;im.onerror=reject;});return im.naturalWidth>0&&im.naturalHeight>0;}catch{return false;}
}
async function repairEngineIcons(){
 if(repairingIcons)throw Error('正在获取图标，请稍候');repairingIcons=true;const owner=profileState.active;let ok=0,skip=0;const failed=[];
 try{const list=cfg.engines.map(e=>({...e}));for(let i=0;i<list.length;i++){
  if(owner!==profileState.active)throw Error('配置已切换，已停止；已获取图标已保存');const e=list[i];if(await usableStoredIcon(e)){skip++;continue;}
  toast(`获取缺失图标 ${i+1}/${list.length}：${e.name}`);
  try{const data=await acquireIcon({...e,icon:'',autoIcon:'',capturedIcon:''});if(owner!==profileState.active)throw Error('配置已切换');const current=cfg.engines.find(x=>x.id===e.id);if(!current||current.iconOrigin==='upload')continue;current.icon=data;current.iconOrigin='auto';current.iconVerified113=true;persist();ok++;}catch(err){if(owner!==profileState.active)throw err;failed.push(e.name);}
 }
 showSettings('engines');toast(`图标：新增 ${ok}，跳过已有 ${skip}，失败 ${failed.length}`);if(failed.length){const p=panel('图标获取结果','textmodal');el('p','未成功：'+failed.join('、')+'。下次仅重试缺失或损坏项。',p);button(p,'返回搜索引擎库',()=>showSettings('engines'));}
 }finally{repairingIcons=false;}
}

